// === Tab: IsoCube ===
class IsoCube {

	constructor(x, y, s, w, h, clr, len, typ = 0) {
		// const sx = (x - y) * s * sclX * Math.sqrt(3) * 0.5;
		// const sy = s * sclX / 2 +  x * s * sclX * 0.5 +  y * s * sclY * 0.5;
		this.pos = this.getPos(x, y, s)
		this.x = x; // sx; // pos x
		this.y = y; // sy; // pos y
		this.s = s; // size
		this.w = w; // size
		this.h = h; // size
		// this.h = h; // hue color
		this.clr = clr;
		this.len = len; //  || s; // length
		this.typ = typ;
	}

	// https://en.wikipedia.org/wiki/Isometric_projection
	getPos(xi, yi, sze) {
		const x = (xi - yi) * sze * Math.sqrt(3) * 0.5;
		const y = sze / 2 +  xi * sze * 0.5 +  yi * sze * 0.5;
		return {x, y};
	}

	show(f = 1) {
		push()
		rectMode(CENTER)
		colorMode(HSB)

		translate(this.pos.x, this.pos.y);

		const l = this.len * f; // this.s;
		const pN = this.getPos(0, 0, this.s);
		const pE = this.getPos(this.w, 0, this.s);
		const pS = this.getPos(this.w, this.h, this.s);
		const pW = this.getPos(0, this.h, this.s);

		colorMode(HSB);
		let clr = this.clr;
		let cHue = hue(window.color(clr)); // this.h;
		let cSat = saturation(window.color(clr));
		let cBri = brightness(window.color(clr));
		let alpha = 0.95;

		// base
		// fill(hue, 50, 50, alpha)
		fill(cHue, cSat, cBri, alpha)
		quad(pN.x, pN.y, pE.x, pE.y, pS.x, pS.y, pW.x, pW.y);

		// height?
		if (l > 0)  {			
			// top
			// fill(hue, 75, 60, alpha)
			fill(cHue, constrain(cSat + 25, 0, 100), constrain(cBri + 10, 0, 100), alpha)
			quad(pN.x, pN.y - l, pE.x, pE.y - l, pS.x, pS.y - l, pW.x, pW.y - l);
			// right
			// fill(hue, 85, 25, alpha)
			fill(cHue, constrain(cSat + 35, 0, 100), constrain(cBri - 25, 0, 100), alpha)
			quad(pE.x, pE.y - l, pE.x, pE.y, pS.x, pS.y, pS.x, pS.y - l);
			// left
			// fill(hue, 65, 75, alpha)
			fill(cHue, constrain(cSat + 15, 0, 100), constrain(cBri + 25, 0, 100), alpha)
			quad(pW.x, pW.y - l, pW.x, pW.y, pS.x, pS.y, pS.x, pS.y - l);
		}

		pop()
	}

}

