	gradient.addColorStop(1, color("silver"));
	ctx.fillStyle = gradient;
	ctx.fillRect(0, 0, width, height);	

	// cubes
	push()
	translate(width * 0.5, height * 0.5 - NUM * SZE * 0.5)
	for (let item of grid) {
		// item.l = item.s + sin((frameCount * 0.02+ item.x + item.y) ) * item.s * 0.5;
		// item.l = Math.pow(item.s, noise(width + item.x, height + item.y, frameCount * 0.005) + 0.65); // map(noise(item.x, item.y, frameCount * 0.005), 0, 1, 0, item.s * 3)
		/* if (item.l > 0) */ // item.l = max(SZE, Math.pow(Math.pow(item.s, noise(width + item.x, height + item.y, frameCount * 0.0025) + 0.45), 1.25));
		n = (noise(width + item.x * 0.123, height + item.y * 0.321, frameCount * 0.0025) + 0.25);
